/* Portal da Cidade — shell, roteador e páginas públicas */
'use strict';
const V={};
const ACT={},FORM={};
const go=h=>{if(location.hash==='#'+h)route();else location.hash=h};
const ph=(t,s='',crumb='')=>`<div class="ph"><div class="wrap">${crumb?`<div class="crumb">${crumb}</div>`:''}<h1>${t}</h1>${s?`<p class="muted" style="margin:0;max-width:720px">${s}</p>`:''}</div></div>`;
const sec=(title,sub,link,body,cls='')=>`<section class="sec ${cls}"><div class="wrap"><div class="sec-h"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${link?`<a href="${link[0]}">${link[1]} ${ic('right','s')}</a>`:''}</div>${body}</div></section>`;
const fAttr=o=>`data-f="${esc(JSON.stringify(o))}"`;

/* ---------- shell ---------- */
const NAV=[['categorias','Categorias'],['empresas','Empresas'],['servicos','Serviços'],['eventos','Eventos'],['turismo','Turismo'],['ofertas','Ofertas'],['telefones-uteis','Telefones úteis'],['empregos','Empregos'],['noticias','Notícias'],['mapa','Mapa']];
function renderHeader(){const h=$('#hdr');if(h.contains(document.activeElement)&&document.activeElement.tagName==='INPUT')return;const st=site();const n=S.route?.n||'';const me=S.me;const uname=me?.name||'';h.innerHTML=`<div class="wrap hbar"><a class="brand" href="#inicio" aria-label="${esc(st.name)} — início">${LOGO}<span><b>${esc(st.name)}</b><small>${esc(st.city)}${st.state?' – '+esc(st.state):''}</small></span></a>
<form class="hsearch" data-form="hdrSearch" role="search">${ic('search')}<input name="q" type="search" placeholder="Buscar empresas, serviços, produtos…" aria-label="Buscar no portal" value="${esc(S.f.q)}"></form>
<div class="hact"><a class="btn btn-p hide-m" href="#${S.uid&&me?.acceptedAt?'painel-nova':'cadastro'}">${ic('store','s')}<span>Cadastre sua empresa</span></a>
${S.uid?`<div class="umenu" id="umenu"><button class="btn btn-g" data-act="umenu" aria-haspopup="true" aria-label="Menu da conta"><span class="avatar">${esc(initials(uname||'Você'))}</span></button><div class="udrop"><div class="sm muted" style="padding:8px 12px">${esc(uname||'Conta conectada')}</div><a href="#painel">${ic('grid','s')} Painel do empresário</a>${S.admin?`<a href="#admin">${ic('shield','s')} Administração</a>`:''}<a href="#painel-config">${ic('cog','s')} Configurações da conta</a></div></div>`:`<a class="btn hide-m" href="#entrar">${ic('user','s')} Entrar</a>`}
<button class="btn btn-g menuBtn" data-act="drawer" aria-label="Abrir menu">${ic('menu')}</button></div></div>
<nav class="nav" aria-label="Seções do portal"><div class="wrap">${NAV.map(([k,l])=>`<a href="#${k}" class="${n===k||n.startsWith(k.slice(0,-1)+'*')?'on':''}">${l}</a>`).join('')}</div></nav>`;
 $('#bottomNav').innerHTML=[['inicio','home','Início'],['empresas','search','Buscar'],['ofertas','tag','Ofertas'],['eventos','cal','Eventos'],[S.uid?'painel':'entrar','user',S.uid?'Painel':'Entrar']].map(([k,i,l])=>`<a href="#${k}" class="${n===k?'on':''}">${ic(i)}${l}</a>`).join('');}
function renderDrawer(){$('#drawer').innerHTML=`<div class="bk" data-act="drawerClose"></div><div class="pn" role="dialog" aria-label="Menu"><div class="row between" style="margin-bottom:10px"><b>${esc(site().name)}</b><button class="btn btn-g btn-sm" data-act="drawerClose" aria-label="Fechar">${ic('x')}</button></div><form data-form="hdrSearch" class="fld"><input name="q" type="search" class="inp" placeholder="Buscar na cidade" aria-label="Buscar"></form>${[['inicio','home','Início'],...NAV.map(([k,l])=>[k,{categorias:'layers',empresas:'store',servicos:'brief',eventos:'cal',turismo:'travel',ofertas:'tag','telefones-uteis':'phone',empregos:'brief',noticias:'news',mapa:'map'}[k],l]),['bairros','pin','Bairros e zonas'],['planos','star','Planos para empresas']].map(([k,i,l])=>`<a href="#${k}">${ic(i)}${l}</a>`).join('')}<div style="height:1px;background:var(--line);margin:10px 0"></div><a class="btn btn-p btn-block" href="#${S.uid?'painel-nova':'cadastro'}" style="justify-content:center;color:#2A1B0E">Cadastre sua empresa</a>${S.uid?`<a href="#painel">${ic('grid')}Painel do empresário</a>${S.admin?`<a href="#admin">${ic('shield')}Administração</a>`:''}`:`<a href="#entrar">${ic('user')}Entrar</a>`}</div>`}
function renderFooter(){const st=site();$('#ftr').innerHTML=`<div class="wrap"><div class="fcols"><div><div class="row" style="margin-bottom:10px">${LOGO.replace('<svg','<svg width="34" height="34"')}<b style="color:#fff;font-family:Montserrat;font-size:18px">${esc(st.name)}</b></div><p class="sm">${esc(st.tagline)}. O guia digital de ${esc(st.city)} para moradores, turistas e empresas.</p>${st.email?`<p class="sm">Contato: ${esc(st.email)}</p>`:''}</div><div><h4>Explorar</h4><ul><li><a href="#empresas">Empresas</a></li><li><a href="#ofertas">Ofertas</a></li><li><a href="#eventos">Eventos</a></li><li><a href="#turismo">Turismo</a></li><li><a href="#bairros">Bairros</a></li></ul></div><div><h4>Utilidade</h4><ul><li><a href="#telefones-uteis">Telefones úteis</a></li><li><a href="#empregos">Empregos</a></li><li><a href="#noticias">Notícias</a></li><li><a href="#mapa">Mapa</a></li></ul></div><div><h4>Para empresas</h4><ul><li><a href="#cadastro">Cadastre sua empresa</a></li><li><a href="#planos">Planos</a></li><li><a href="#painel">Painel do empresário</a></li><li><a href="#termos">Termos de uso</a></li><li><a href="#privacidade">Privacidade e LGPD</a></li></ul></div></div><div class="fbot"><span>© ${new Date().getFullYear()} ${esc(st.name)} · ${esc(st.city)}</span><span>Protótipo funcional — dados marcados como “Demonstração” são fictícios.</span></div></div>`}

/* ---------- roteador ---------- */
function parseRoute(){const h=decodeURIComponent(location.hash.replace(/^#/,''))||'inicio';if(V[h])return[h,null];for(const p of['empresa','categoria','evento','noticia','turismo']){if(h.startsWith(p+'-')&&V[p+'*'])return[p+'*',h.slice(p.length+1)]}return['404',h]}
function route(){const[n,param]=parseRoute();S.route={n,param};$('#drawer').classList.remove('on');$('#umenu')?.classList.remove('open');render(true)}
let wasReady=false;
function render(nav){const{n,param}=S.route;let v=V[n]||V['404'];const app=$('#app');let html;
 const st=site();
 if(v.auth&&S.uid===null&&S.userResolved){html=needLogin()}
 else if(v.auth==='admin'&&S.userResolved&&!S.admin){html=ph('Acesso restrito')+`<div class="wrap sec">${empty('Você não tem permissão de administrador.','A administração é liberada para quem tem nível Editor ou Proprietário neste portal.')}</div>`}
 else if(!coreReady()||(v.auth&&!S.userResolved)){html=loadingView()}
 else if(v.auth==='profile'&&!S.me?.acceptedAt){location.replace('#cadastro');return}
 else{try{html=v.render(param)}catch(e){console.error(e);html=ph('Algo deu errado')+`<div class="wrap sec">${empty('Não foi possível exibir esta página.',esc(e.message||''))}</div>`}
  if(v.layout==='painel')html=painelLayout(html,v.key||n);if(v.layout==='admin')html=adminLayout(html,v.key||n)}
 const y=window.scrollY;app.innerHTML=html;
 document.title=(typeof v.title==='function'?v.title(param):v.title||'')+(v.title?' · ':'')+st.name;
 if(nav)window.scrollTo(0,0);else window.scrollTo(0,y);
 if(coreReady()&&v.after)try{v.after(param)}catch(e){console.error(e)}
 fillNames(app);renderHeader()}
function onData(){const ready=coreReady();renderHeader();renderFooter();if(!S.route)return;const v=V[S.route.n]||V['404'];const ae=document.activeElement;const typing=ae&&$('#app').contains(ae)&&/INPUT|TEXTAREA|SELECT/.test(ae.tagName);if(!wasReady&&ready){wasReady=true;render(false);return}if(v.live===false||typing){if(!typing&&v.refresh)try{v.refresh()}catch(e){console.error(e)}return}render(false)}
function loadingView(){const slow=S.slow?`<div class="note or" style="margin-bottom:16px">${ic('alert')} Os dados ainda não puderam ser carregados. Verifique a conexão — esta página atualiza sozinha quando o banco responder.</div>`:'';return`<div class="wrap sec">${slow}<div class="skel" style="height:46px;width:40%;margin-bottom:18px"></div>${skeletons(4)}</div>`}
function needLogin(){return ph('Entre para continuar')+`<div class="wrap sec"><div class="card" style="max-width:620px">${ic('lock','l')}<h3 style="margin-top:10px">Esta área é exclusiva para contas conectadas</h3><p class="muted">O acesso usa a sua conta conectada a este portal. Abra o portal com sua conta e volte a esta página.</p><a class="btn" href="#entrar">Saiba como entrar</a></div></div>`}

/* ---------- busca ---------- */
function searchCompanies(f){const q=slugify(f.q||'').split('-').filter(w=>w.length>1);let list=pubCompanies().map(c=>{let s=0;if(q.length){const name=slugify(c.pubName),kw=slugify((c.keywords||'')+' '+(c.subs||[]).map(catName).join(' ')+' '+catName(c.pubCat)),desc=slugify((c.description||'')+' '+(c.products||[]).map(p=>p.name+' '+(p.desc||'')).join(' ')),loc=slugify(bairroName(c.loc?.bairro)+' '+(zoneById(c.loc?.zone)?.name||''));for(const w of q){if(name.includes(w))s+=5;if(kw.includes(w))s+=3;if(desc.includes(w))s+=1;if(loc.includes(w))s+=1}if(!s)return null}return{c,s}}).filter(Boolean);
 if(f.cat)list=list.filter(({c})=>c.allCats.includes(f.cat)||c.allCats.some(id=>catById(id)?.parent===f.cat));
 if(f.sub)list=list.filter(({c})=>c.allCats.includes(f.sub));
 if(f.zone)list=list.filter(({c})=>c.loc?.zone===f.zone);
 if(f.bairro)list=list.filter(({c})=>c.loc?.bairro===f.bairro);
 if(f.open)list=list.filter(({c})=>isOpen(c)===true);
 if(f.promo){const ids=new Set(activePromos().map(p=>p.companyId));list=list.filter(({c})=>ids.has(c.id))}
 if(f.home)list=list.filter(({c})=>c.estab==='domiciliar'||c.estab==='hibrido');
 if(f.verified)list=list.filter(({c})=>c.verified);
 if(f.minRating)list=list.filter(({c})=>(ratingOf(c.id)?.avg||0)>=f.minRating);
 if(f.type)list=list.filter(({c})=>c.estab===f.type);
 const nb=f.near?bairroById(f.near):null;const prox=c=>!nb?0:c.loc?.bairro===nb.id?2:c.loc?.zone===nb.zone?1:0;
 list.sort((a,b)=>{if(f.sort==='nome')return a.c.pubName.localeCompare(b.c.pubName);if(f.sort==='recentes')return(b.c.approvedAt||0)-(a.c.approvedAt||0);if(f.sort==='avaliacao')return(ratingOf(b.c.id)?.avg||0)-(ratingOf(a.c.id)?.avg||0);if(nb){const d=prox(b.c)-prox(a.c);if(d)return d}return(b.s-a.s)||((b.c.featured?1:0)-(a.c.featured?1:0))||a.c.pubName.localeCompare(b.c.pubName)});
 return list.map(x=>x.c)}
FORM.hdrSearch=(f,o)=>{S.f={...F0,q:o.q||''};go('empresas')};
FORM.heroSearch=(f,o)=>{S.f={...F0,q:o.q||'',cat:o.cat||'',...(o.loc?.startsWith('z:')?{zone:o.loc.slice(2)}:o.loc?.startsWith('b:')?{bairro:o.loc.slice(2)}:{})};go('empresas')};
function locOptions(sel=''){return zones().map(z=>`<optgroup label="${esc(z.name)}"><option value="z:${esc(z.id)}" ${sel==='z:'+z.id?'selected':''}>Toda a zona ${esc(z.name)}</option>${(z.bairros||[]).map(b=>`<option value="b:${esc(b.id)}" ${sel==='b:'+b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</optgroup>`).join('')}

/* ---------- home ---------- */
const HERO_ART=`<svg class="bgart" viewBox="0 0 1200 520" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><pattern id="dots" width="22" height="22" patternUnits="userSpaceOnUse"><circle cx="2" cy="2" r="1.3" fill="#55B7D9" opacity=".28"/></pattern></defs><rect x="640" y="0" width="560" height="520" fill="url(#dots)"/><g fill="none" stroke="#718A52" stroke-width="1.2" opacity=".22">${Array.from({length:9},(_,i)=>`<path d="M${520+i*8} 520 C ${700+i*20} ${380-i*22}, ${900+i*10} ${460-i*30}, 1220 ${300-i*26}"/>`).join('')}</g><g fill="none" stroke="#E88936" stroke-width="1.4" opacity=".25"><path d="M0 470 C 200 420, 380 500, 620 440"/></g></svg>`;
function catTile(c){const col=CATCOLOR[c.icon]||'#287DA3';const n=pubCompanies().filter(x=>x.allCats.includes(c.id)||x.allCats.some(id=>catById(id)?.parent===c.id)).length;return`<button class="cat" ${fAttr({cat:c.id})}><span class="ci" style="background:${col}1a;color:${col}">${ic(c.icon,'l')}</span><b>${esc(c.name)}</b><small>${n?nf(n)+' empresa'+(n>1?'s':''):'Seja o primeiro'}</small></button>`}
function adSlot(pl){const t=dayKey();const ads=S.ads.filter(a=>a.placement===pl&&a.active!==false&&(!a.start||a.start<=t)&&(!a.end||a.end>=t));if(!ads.length)return'';const a=ads[Math.floor(Math.random()*ads.length)];const u=safeImg(a.image?.url);const href=a.companyId&&compById(a.companyId)?'#empresa-'+compById(a.companyId).slug:a.link?(a.link.startsWith('#')?a.link:safeUrl(a.link)):'#planos';return`<div class="wrap" style="margin:8px auto"><a class="ad" href="${esc(href)}" ${href.startsWith('http')?'target="_blank" rel="noopener"':''}><span class="lbl">Publicidade</span><div><h3 style="margin:0 0 4px">${esc(a.title)}</h3>${a.text?`<p class="muted" style="margin:0">${esc(a.text)}</p>`:''}</div>${u?`<img src="${u}" alt="">`:`<span class="btn btn-p">Saiba mais</span>`}</a></div>`}
function companiesIn(catId,n=4){return pubCompanies().filter(c=>c.allCats.includes(catId)||c.allCats.some(id=>catById(id)?.parent===catId)).sort((a,b)=>(b.featured?1:0)-(a.featured?1:0)).slice(0,n)}
V.inicio={title:'Início',render(){const st=site();const pc=pubCompanies();const promos=activePromos();const evs=upcomingEvents();
 const top=mainCats().map(c=>[c,pc.filter(x=>x.allCats.includes(c.id)||x.allCats.some(id=>catById(id)?.parent===c.id)).length]).sort((a,b)=>b[1]-a[1]||((a[0].order||0)-(b[0].order||0))).slice(0,12).map(x=>x[0]);
 const featured=pc.filter(c=>c.featured).slice(0,8);const feat=featured.length?featured:pc.slice().sort((a,b)=>(b.approvedAt||0)-(a.approvedAt||0)).slice(0,4);
 const food=companiesIn('alimentacao');const shop=[...companiesIn('vestuario',3),...companiesIn('casa-decoracao',3)].slice(0,4);const agro=companiesIn('agronegocio');
 const recent=pc.slice().sort((a,b)=>(b.approvedAt||0)-(a.approvedAt||0)).slice(0,4);
 const emerg=S.phones.slice().sort((a,b)=>(a.category==='Emergência'?0:1)-(b.category==='Emergência'?0:1)||(a.order||99)-(b.order||99)).slice(0,6);
 const tour=S.tourism.slice(0,3);
 const grid=(arr,fn,cls='g4',emptyMsg=['Nada por aqui ainda.',''])=>arr.length?`<div class="grid ${cls}">${arr.map(fn).join('')}</div>`:empty(...emptyMsg);
 return`<section class="hero">${HERO_ART}<div class="wrap"><div><div class="eyebrow">${esc(st.tagline)}</div><h1>${esc(st.heroTitle).replace(/Tudo em um só lugar\./,'<span>Tudo em um só lugar.</span>')}</h1><p class="lead">${esc(st.heroSub)}</p>
 <form class="sbox" data-form="heroSearch" role="search"><label class="f">${ic('search')}<span class="sr">O que você procura</span><input name="q" placeholder="O que você está procurando?"></label><label class="f">${ic('layers')}<span class="sr">Categoria</span><select name="cat"><option value="">Todas as categorias</option>${mainCats().map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></label><label class="f">${ic('pin')}<span class="sr">Zona ou bairro</span><select name="loc"><option value="">Zona ou bairro</option>${locOptions()}</select></label><button class="btn btn-p">Buscar na cidade</button></form>
 <div class="qchips">${[['Comércio','vestuario','store'],['Serviços','servicos-profissionais','brief'],['Alimentação','alimentacao','food'],['Agro','agronegocio','leaf'],['Turismo','turismo','travel']].filter(x=>catById(x[1])).map(([l,id,i])=>`<a href="#empresas" ${fAttr({cat:id})}>${ic(i,'s')}${l}</a>`).join('')}<a href="#eventos">${ic('cal','s')}Eventos</a></div></div>
 <div class="hcard"><div class="row between"><b style="font-family:Montserrat">Agora em ${esc(st.city)}</b><span class="chip chip-vd">${ic('leaf','s')}Comércio local</span></div><div class="hstats"><div><b>${nf(pc.length)}</b><span>empresas</span></div><div><b>${nf(promos.length)}</b><span>ofertas ativas</span></div><div><b>${nf(evs.length)}</b><span>próximos eventos</span></div></div><div class="list" style="margin-top:14px">${promos.slice(0,2).map(p=>`<a class="li" href="#empresa-${esc(p.company.slug)}" style="text-decoration:none;color:inherit"><div class="ico" style="background:#fdf0e3;color:#b25f17">${ic('tag')}</div><div class="grow"><b class="sm">${esc(p.title)}</b><div class="xs muted">${esc(p.company.pubName)}</div></div>${discount(p)?`<span class="chip chip-or">-${discount(p)}%</span>`:''}</a>`).join('')||`<div class="note">${ic('store')} Cadastre sua empresa e publique a primeira oferta da cidade.</div>`}</div><a class="btn btn-b btn-block" style="margin-top:14px" href="#${S.uid?'painel-nova':'cadastro'}">Cadastrar minha empresa</a></div></div></section>
 ${sec('Categorias mais procuradas','Navegue pelos segmentos do comércio e dos serviços locais.',['#categorias','Ver todas'],top.length?`<div class="catgrid">${top.map(catTile).join('')}</div>`:empty('Nenhuma categoria cadastrada.','O administrador cria as categorias em Administração → Categorias.'))}
 ${adSlot('home-topo')}
 ${sec('Empresas em destaque','',['#empresas','Ver empresas'],grid(feat,cCard,'g4',['Nenhuma empresa publicada ainda.','As empresas aparecem aqui após a aprovação.']),'alt')}
 ${sec('Encontre serviços na sua região','Escolha a zona ou o bairro e veja quem atende perto de você.',['#bairros','Todos os bairros'],zones().length?`<div class="zones">${zones().map(z=>{const n=pc.filter(c=>c.loc?.zone===z.id).length;return`<button class="zone" ${fAttr({zone:z.id})}><h4>${ic('pin','s')} ${esc(z.name)}</h4><span class="sm muted">${nf(n)} empresa${n===1?'':'s'}</span><div class="bx">${(z.bairros||[]).slice(0,4).map(b=>`<span class="chip chip-gy">${esc(b.name)}</span>`).join('')}</div></button>`}).join('')}</div>`:empty('Zonas ainda não configuradas.'))}
 ${sec('Promoções da cidade','Ofertas publicadas pelas próprias empresas.',['#ofertas','Todas as ofertas'],grid(promos.slice(0,8),pCard,'g4',['Nenhuma oferta ativa no momento.','Empresas cadastradas podem publicar promoções pelo painel.']),'alt')}
 ${sec('Próximos eventos','',['#eventos','Agenda completa'],evs.length?`<div class="grid g2">${evs.slice(0,4).map(eCard).join('')}</div>`:empty('Nenhum evento agendado.'))}
 ${food.length?sec('Gastronomia','Restaurantes, padarias, cafés e muito mais.',['#categoria-alimentacao','Ver gastronomia'],grid(food,cCard),'alt'):''}
 ${shop.length?sec('Comércio e lojas','',['#empresas','Ver lojas'],grid(shop,cCard)):''}
 ${sec('Turismo e cultura','História, roteiros e experiências da região.',['#turismo','Explorar turismo'],tour.length?`<div class="grid g3">${tour.map(tCard).join('')}</div>`:empty('Conteúdo turístico em preparação.'),'alt')}
 ${sec(`${ic('leaf')} Agronegócio e setor rural`,'Agropecuárias, produtores, insumos e serviços para o campo.',['#categoria-agronegocio','Ver agronegócio'],grid(agro,cCard,'g4',['Nenhuma empresa do agro publicada ainda.','']),'agro')}
 ${adSlot('home-meio')}
 ${sec('Vagas de emprego','',['#empregos','Todas as vagas'],allJobs().length?`<div class="list">${allJobs().slice(0,4).map(jobItem).join('')}</div>`:empty('Nenhuma vaga aberta no momento.'))}
 ${sec('Notícias locais','',['#noticias','Todas as notícias'],grid(pubNews().slice(0,3),nCard,'g3',['Nenhuma notícia publicada.','']),'alt')}
 ${sec('Telefones úteis','Emergência e serviços essenciais.',['#telefones-uteis','Ver todos'],emerg.length?`<div class="grid g3">${emerg.map(phoneItem).join('')}</div>`:empty('Lista em preparação.'))}
 ${sec('Empresas recém-cadastradas','',['#empresas','Ver todas'],grid(recent,cCard,'g4',['Ainda não há empresas aprovadas.','']),'alt')}
 <section class="sec"><div class="wrap"><div class="cta"><svg class="art" viewBox="0 0 40 40">${LOGO.replace(/<\/?svg[^>]*>/g,'')}</svg><div><h2>Sua empresa ainda não está aqui?</h2><p>Cadastre gratuitamente, monte sua página com fotos, horários e WhatsApp e publique promoções para toda a cidade — sem precisar de conhecimento técnico.</p></div><div class="row" style="justify-content:flex-end"><a class="btn btn-p" href="#${S.uid?'painel-nova':'cadastro'}">Cadastrar gratuitamente</a><a class="btn" href="#planos" style="background:transparent;color:#fff;border-color:rgba(255,255,255,.4)">Conhecer planos</a></div></div></div></section>`}};
function tCard(t){const u=safeImg(t.image?.url);return`<a class="ncard" href="#turismo-${esc(t.id)}"><div class="ni" style="${u?`background-image:url('${u}')`:'background:linear-gradient(135deg,var(--vd),#4d9a8a)'}"></div><div class="nb"><span class="chip chip-vd">${esc(t.kind||'Turismo')}</span><h4 style="margin:10px 0 6px">${esc(t.title)}</h4><p class="sm muted" style="margin:0">${esc(t.summary||'')}</p>${demoTag(t)}</div></a>`}

/* ---------- diretório ---------- */
function filtersHtml(){const f=S.f;const subs=f.cat?subCats(f.cat):[];const z=f.zone?zoneById(f.zone):null;const bairros=z?(z.bairros||[]):allBairros();return`<div class="row between"><b>Filtros</b><button class="btn btn-g btn-sm" data-act="clearF">Limpar</button></div><div class="fbody"><h4>Busca</h4><input class="inp" type="search" data-fk="q" value="${esc(f.q)}" placeholder="Nome, produto, serviço…" aria-label="Termo de busca">
<h4>Categoria</h4><select class="inp" data-fk="cat" aria-label="Categoria"><option value="">Todas</option>${mainCats().map(c=>`<option value="${esc(c.id)}" ${f.cat===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select>${subs.length?`<select class="inp" data-fk="sub" aria-label="Subcategoria" style="margin-top:8px"><option value="">Todas as subcategorias</option>${subs.map(c=>`<option value="${esc(c.id)}" ${f.sub===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select>`:''}
<h4>Localização</h4><select class="inp" data-fk="zone" aria-label="Zona"><option value="">Todas as zonas</option>${zones().map(z=>`<option value="${esc(z.id)}" ${f.zone===z.id?'selected':''}>${esc(z.name)}</option>`).join('')}</select><select class="inp" data-fk="bairro" aria-label="Bairro" style="margin-top:8px"><option value="">Todos os bairros</option>${bairros.map(b=>`<option value="${esc(b.id)}" ${f.bairro===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select>
<h4>Perto de mim</h4><select class="inp" data-fk="near" aria-label="Seu bairro"><option value="">Informe seu bairro</option>${allBairros().map(b=>`<option value="${esc(b.id)}" ${f.near===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select><p class="xs muted" style="margin:6px 0 0">Ordena por proximidade: mesmo bairro, depois mesma zona.</p>
<h4>Refinar</h4>${[['open','Aberto agora'],['promo','Com promoções'],['home','Atendimento domiciliar'],['verified','Empresas verificadas']].map(([k,l])=>`<label class="chk"><input type="checkbox" data-fk="${k}" ${f[k]?'checked':''}>${l}</label>`).join('')}
<h4>Avaliação mínima</h4><select class="inp" data-fk="minRating" aria-label="Avaliação mínima"><option value="0">Qualquer</option>${[3,4,4.5].map(r=>`<option value="${r}" ${+f.minRating===r?'selected':''}>${String(r).replace('.',',')}+ estrelas</option>`).join('')}</select>
<h4>Tipo de atendimento</h4><select class="inp" data-fk="type" aria-label="Tipo"><option value="">Todos</option>${Object.entries(ESTAB).map(([k,l])=>`<option value="${k}" ${f.type===k?'selected':''}>${l}</option>`).join('')}</select></div>`}
let resLimit=24;
function renderResults(){const box=$('#results');if(!box)return;const list=searchCompanies(S.f);$('#resCount').textContent=`${nf(list.length)} resultado${list.length===1?'':'s'}`;box.innerHTML=(list.length?`<div class="grid g3">${list.slice(0,resLimit).map(cCard).join('')}</div>${list.length>resLimit?`<div style="text-align:center;margin-top:20px"><button class="btn" data-act="more">Carregar mais</button></div>`:''}`:empty('Nenhuma empresa encontrada com esses filtros.','Tente remover algum filtro ou buscar por outro termo.',`<button class="btn" data-act="clearF">Limpar filtros</button>`))+adSlot('diretorio')}
function bindFilters(){const p=$('#filters');if(!p)return;let t;p.addEventListener('input',e=>{const k=e.target.dataset.fk;if(!k)return;const el=e.target;const val=el.type==='checkbox'?el.checked:k==='minRating'?+el.value:el.value;S.f[k]=val;if(k==='cat'){S.f.sub='';p.innerHTML=filtersHtml()}if(k==='zone'){S.f.bairro='';p.innerHTML=filtersHtml()}resLimit=24;clearTimeout(t);t=setTimeout(renderResults,k==='q'?220:0)});}
ACT.more=()=>{resLimit+=24;renderResults()};
ACT.clearF=()=>{S.f={...F0};const p=$('#filters');if(p)p.innerHTML=filtersHtml();renderResults()};
ACT.toggleF=()=>$('#filters')?.classList.toggle('collapsed');
V.empresas={title:'Empresas',live:false,render(){return ph('Empresas e profissionais',`Guia comercial de ${esc(site().city)}: encontre por categoria, zona, bairro e mais.`)+`<div class="wrap dir"><aside class="filters" id="filters" aria-label="Filtros">${filtersHtml()}</aside><div><div class="row between" style="margin-bottom:14px"><div id="resCount" class="muted" aria-live="polite"></div><div class="row"><label class="sr" for="fSort">Ordenar</label><select id="fSort" class="inp" style="width:auto;min-height:40px">${[['relevancia','Relevância'],['nome','Nome (A–Z)'],['recentes','Mais recentes'],['avaliacao','Melhor avaliadas']].map(([k,l])=>`<option value="${k}" ${S.f.sort===k?'selected':''}>${l}</option>`).join('')}</select></div></div><div id="results"></div></div></div>`},after(){bindFilters();$('#fSort').onchange=e=>{S.f.sort=e.target.value;renderResults()};renderResults()},refresh(){renderResults()}};

/* ---------- página da empresa ---------- */
function mapsUrl(c){if(c.loc?.lat&&c.loc?.lng)return`https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(c.loc.lat+','+c.loc.lng)}`;const a=[c.loc?.street,c.loc?.number,bairroName(c.loc?.bairro),c.loc?.city||site().city,site().state].filter(Boolean).join(', ');return a?`https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(a)}`:''}
function addrText(c){const l=c.loc||{};return[[l.street,l.number].filter(Boolean).join(', '),l.complement,bairroName(l.bairro),zoneById(l.zone)?.name?'Zona '+zoneById(l.zone).name:'',l.city||site().city,l.cep?'CEP '+l.cep:''].filter(Boolean).join(' · ')}
function hoursTable(c){const h=c.hours;if(!h?.week)return'<p class="muted sm">Horário não informado.</p>';const today=DAYS[new Date().getDay()];return`<table class="hours">${WEEK.map(d=>{const x=h.week[d]||{};return`<tr class="${d===today?'today':''}"><td>${DAYL[d]}</td><td style="text-align:right">${x.closed||!x.open?'Fechado':`${esc(x.open)}–${esc(x.close)}${x.breakStart?`<br><span class="xs muted">intervalo ${esc(x.breakStart)}–${esc(x.breakEnd)}</span>`:''}`}</td></tr>`}).join('')}</table>${(h.special||[]).filter(s=>s.date>=dayKey()).length?`<p class="sm" style="margin:10px 0 4px"><b>Horários especiais</b></p>${h.special.filter(s=>s.date>=dayKey()).map(s=>`<div class="sm">${fmtD(s.date)} — ${esc(s.label||'')} ${s.closed?'(fechado)':`${esc(s.open||'')}–${esc(s.close||'')}`}</div>`).join('')}`:''}${h.notes?`<p class="xs muted" style="margin-top:8px">${esc(h.notes)}</p>`:''}`}
function miniMap(c){const z=c.loc?.zone;const zs=zones();const idx=Math.max(0,zs.findIndex(x=>x.id===z));return`<svg viewBox="0 0 320 170" role="img" aria-label="Localização esquemática"><rect width="320" height="170" fill="#f4f1ea"/><g stroke="#e2dccf" stroke-width="10" fill="none"><path d="M0 120 C 80 100, 160 140, 320 90"/><path d="M110 0 C 120 60, 90 110, 140 170"/></g><g stroke="#fff" stroke-width="3" fill="none"><path d="M0 60 L320 70M220 0 L240 170"/></g><circle cx="${90+idx*28%160}" cy="${60+(idx*37)%60}" r="30" fill="var(--azc)" opacity=".15"/><g transform="translate(${90+idx*28%160} ${60+(idx*37)%60})"><path d="M0 0c-8 0-14-6-14-13.5C-14-24 0-36 0-36s14 12 14 22.5C14-6 8 0 0 0z" fill="var(--lj)" transform="translate(0 6)"/><circle cy="-8" r="5" fill="#fff"/></g><text x="12" y="158" font-size="11" fill="#7b858a">Mapa esquemático · ${esc(zoneById(z)?.name||'')}</text></svg>`}
function companyPage(c,{draft=false,preview=false}={}){const name=draft?c.name:c.pubName;const cat=draft?c.mainCat:c.pubCat;const ct=c.contacts||{};const wa=waLink(ct.whatsapp,`Olá! Encontrei ${name} no ${site().name}.`);const tel=digits(ct.phone||ct.whatsapp);const route=c.loc?.hideAddress?'':mapsUrl(c);const r=ratingOf(c.id);const o=isOpen(c);const promos=draft?[]:activePromos().filter(p=>p.companyId===c.id);const gal=c.gallery||[];const prods=c.products||[];const reviews=draft?[]:reviewsFor(c.id);const related=draft?[]:pubCompanies().filter(x=>x.id!==c.id&&x.pubCat===c.pubCat).slice(0,3);const cid=esc(c.id||'');const coverU=safeImg(c.cover?.url);
 const mine=S.reviews[S.uid]?.items?.[c.id];
 return`<div class="cp-cover" style="${coverU?`background-image:url('${coverU}')`:coverStyle({...c,pubCat:cat})}"></div><div class="wrap"><div class="cp-head">${logoEl({...c,pubName:name,pubCat:cat},'cp-logo')}<div class="cp-title"><div class="row" style="margin-bottom:8px"><span class="chip">${esc(catName(cat)||'Sem categoria')}</span>${c.loc?.bairro?`<span class="chip chip-gy">${ic('pin','s')}${esc(bairroName(c.loc.bairro))}</span>`:''}${c.verified?`<span class="chip chip-gn">${ic('shield','s')}Verificada</span>`:''}${o===true?'<span class="chip chip-gn">Aberto agora</span>':o===false?'<span class="chip chip-gy">Fechado agora</span>':''}${demoTag(c)}</div><h1>${esc(name)}</h1><div class="row">${stars(r)}${c.estab?`<span class="sm muted">${esc(ESTAB[c.estab]||'')}</span>`:''}</div></div></div>
 <div class="cp-actions">${wa?`<a class="btn btn-wa" href="${wa}" target="_blank" rel="noopener" data-track="w" data-cid="${cid}">${ic('wa')} WhatsApp</a>`:''}${tel?`<a class="btn btn-b" href="tel:${tel}" data-track="p" data-cid="${cid}">${ic('phone')} Ligar</a>`:''}${route?`<a class="btn" href="${route}" target="_blank" rel="noopener" data-track="r" data-cid="${cid}">${ic('route')} Como chegar</a>`:''}<button class="btn" data-act="shareC" data-cid="${cid}" data-track="s">${ic('share')} Compartilhar</button></div>
 ${tel?`<p class="xs muted" style="margin:-10px 0 18px">${ct.phone?'Telefone: '+esc(ct.phone):''}${ct.whatsapp?' · WhatsApp: '+esc(ct.whatsapp):''}</p>`:''}
 <div class="cp-grid"><div>
 <div class="card"><h3>Sobre a empresa</h3><p style="white-space:pre-line">${esc(c.description||'Descrição não informada.')}</p><div class="row sm muted">${c.founded?`<span>Desde ${esc(c.founded)}</span>`:''}${(c.subs||[]).map(id=>`<span class="chip chip-gy">${esc(catName(id))}</span>`).join('')}${(c.extraCats||[]).map(id=>`<span class="chip chip-gy">${esc(catName(id))}</span>`).join('')}</div></div>
 ${gal.length?`<div class="card"><h3>Galeria de fotos</h3><div class="cp-gal">${gal.map((g,i)=>`<button data-act="lightbox" data-src="${esc(safeImg(g.url))}" data-cap="${esc(g.caption||'')}" aria-label="Ampliar foto ${i+1}"><img src="${esc(safeImg(g.url))}" alt="${esc(g.caption||'Foto de '+name)}" loading="lazy"></button>`).join('')}</div></div>`:''}
 ${promos.length?`<div class="card"><h3>${ic('tag')} Promoções ativas</h3><div class="grid g2">${promos.map(p=>`<div class="pcard" style="transform:none"><div class="pimg" style="height:120px;${safeImg(p.image?.url)?`background-image:url('${safeImg(p.image.url)}')`:coverStyle(c)}"><span class="pct">${discount(p)?'-'+discount(p)+'%':esc(PROMO_TYPES[p.type]||'Oferta')}</span></div><div class="pbody"><h4>${esc(p.title)}</h4><p class="sm" style="margin:0">${esc(p.desc||'')}</p><div class="price">${num(p.priceFrom)&&num(p.priceTo)?`<s>${money(num(p.priceFrom))}</s>`:''}${num(p.priceTo)?`<b>${money(num(p.priceTo))}</b>`:''}</div>${p.code?`<p class="sm" style="margin:4px 0 0">Cupom: <b>${esc(p.code)}</b></p>`:''}<p class="xs muted" style="margin:4px 0 0">${p.start?'De '+fmtD(p.start)+' ':''}${p.end?'até '+fmtD(p.end):''}${p.qty?` · ${esc(p.qty)} unidades`:''}</p>${p.terms?`<details class="xs"><summary>Termos e condições</summary>${esc(p.terms)}</details>`:''}${p.whatsapp||wa?`<a class="btn btn-wa btn-sm" style="margin-top:8px" target="_blank" rel="noopener" href="${waLink(p.whatsapp||ct.whatsapp,`Olá! Quero aproveitar a promoção "${p.title}".`)}" data-track="w" data-cid="${cid}">${ic('wa','s')} Quero esta oferta</a>`:''}</div></div>`).join('')}</div></div>`:''}
 ${prods.length?`<div class="card"><h3>Produtos e serviços</h3><div class="grid g2">${prods.map(p=>`<div class="prod">${safeImg(p.image?.url)?`<img src="${esc(safeImg(p.image.url))}" alt="">`:`<span class="pi">${ic(p.kind==='servico'?'brief':'box')}</span>`}<div><b>${esc(p.name)}</b><div class="xs muted">${p.kind==='servico'?'Serviço':'Produto'}${num(p.price)?' · '+money(num(p.price)):''}</div>${p.desc?`<div class="sm">${esc(p.desc)}</div>`:''}</div></div>`).join('')}</div></div>`:''}
 ${draft?'':`<div class="card" id="avaliacoes"><h3>Avaliações</h3>${reviews.length?`<div class="list">${reviews.map(rv=>`<div class="li" style="align-items:flex-start;display:block"><div class="row between"><b data-uname="${esc(rv.uid)}">Usuário do portal</b><span class="stars">${'★'.repeat(+rv.rating||0)}<span class="muted" style="font-weight:400">${'★'.repeat(5-(+rv.rating||0))}</span></span></div><p class="sm" style="margin:6px 0 0">${esc(rv.text||'')}</p><div class="xs muted">${fmtD(rv.at)}</div>${c.replies?.[rv.uid]?`<div class="note" style="margin-top:8px"><b>Resposta da empresa:</b> ${esc(c.replies[rv.uid].text)}</div>`:''}</div>`).join('')}</div>`:'<p class="muted sm">Ainda sem avaliações.</p>'}
 ${S.uid&&c.ownerId!==S.uid&&!preview?`<form data-form="review" data-cid="${cid}" style="margin-top:16px;border-top:1px solid var(--line);padding-top:14px"><b class="sm">${mine?'Atualizar sua avaliação':'Avaliar esta empresa'}</b><div class="row" role="radiogroup" aria-label="Nota" style="margin:8px 0">${[1,2,3,4,5].map(n=>`<label class="chk" style="padding:0 6px 0 0"><input type="radio" name="rating" value="${n}" ${+mine?.rating===n?'checked':''} required>${n}★</label>`).join('')}</div><div class="fld"><label for="rvText">Comentário</label><textarea id="rvText" name="text" maxlength="600" placeholder="Conte como foi sua experiência">${esc(mine?.text||'')}</textarea><span class="hint">Avaliações são moderadas e podem ser removidas se violarem as regras de uso.</span></div><button class="btn btn-b btn-sm">Enviar avaliação</button>${mine?` <button type="button" class="btn btn-g btn-sm btn-dl" data-act="delReview" data-cid="${cid}">Remover minha avaliação</button>`:''}</form>`:S.uid?'':'<p class="xs muted">Entre com sua conta para avaliar.</p>'}</div>`}
 ${related.length?`<div style="margin-top:22px"><h3>Empresas relacionadas</h3><div class="grid g3">${related.map(cCard).join('')}</div></div>`:''}
 </div><aside>
 <div class="card"><h3>${ic('clock')} Horário de funcionamento</h3>${hoursTable(c)}</div>
 <div class="card"><h3>Contatos e redes</h3><div class="list">${[[ct.phone,'phone','Telefone',tel?'tel:'+digits(ct.phone):''],[ct.whatsapp,'wa','WhatsApp',wa],[ct.email,'mail','E-mail','mailto:'+(ct.email||'')],[ct.instagram,'insta','Instagram',igLink(ct.instagram)],[ct.facebook,'fb','Facebook',fbLink(ct.facebook)],[ct.site,'globe','Site oficial',safeUrl(ct.site)],[ct.catalog,'list','Catálogo',safeUrl(ct.catalog)]].filter(x=>x[0]).map(([v,i,l,h])=>`<a class="row" href="${esc(h)}" ${/^https/.test(h)?'target="_blank" rel="noopener"':''} data-track="${i==='wa'?'w':i==='phone'?'p':'l'}" data-cid="${cid}" style="gap:10px;color:inherit">${ic(i,'s')}<span class="sm"><b>${l}</b><br>${esc(v)}</span></a>`).join('')||'<p class="muted sm">Sem contatos informados.</p>'}</div></div>
 <div class="card"><h3>${ic('pin')} Endereço</h3>${c.loc?.hideAddress?`<p class="sm">Endereço não divulgado — atendimento ${c.estab==='domiciliar'?'em domicílio':'sob consulta'}.</p>`:`<p class="sm">${esc(addrText(c))||'Endereço não informado.'}</p><div class="mapbox">${miniMap(c)}</div>${route?`<a class="btn btn-sm" style="margin-top:10px" href="${route}" target="_blank" rel="noopener" data-track="r" data-cid="${cid}">${ic('route','s')} Abrir rota no Google Maps</a>`:''}`}${c.loc?.area?`<p class="sm" style="margin-top:10px"><b>Área de atendimento:</b> ${esc(c.loc.area)}</p>`:''}</div>
 </aside></div></div>`}
V['empresa*']={title:p=>compBySlug(p)?.pubName||'Empresa',live:false,render(slug){const c=compBySlug(slug);if(!c)return V['404'].render();const can=c.ownerId===S.uid||S.admin;if(!c.pub&&!can)return ph('Empresa indisponível')+`<div class="wrap sec">${empty('Esta página não está publicada.','Ela pode estar em análise ou suspensa.')}</div>`;const banner=!c.pub?`<div class="preview-banner"><div class="wrap row between"><span>${ic('eye','s')} Pré-visualização — esta página ainda não está pública (${esc(CSTATUS[c.status]?.[0]||c.status)}).</span>${c.ownerId===S.uid?'<a href="#painel-empresa">Editar</a>':''}</div></div>`:c.status==='revisao'&&can?`<div class="preview-banner"><div class="wrap">Alterações sensíveis (nome ou categoria principal) aguardam nova aprovação; o público vê a versão aprovada.</div></div>`:'';return banner+`<div class="wrap crumb" style="padding-top:12px"><a href="#inicio">Início</a> › <a href="#empresas">Empresas</a> › <a href="#categoria-${esc(c.pubCat)}">${esc(catName(c.pubCat))}</a></div>`+companyPage(c,{draft:false})},after(slug){const c=compBySlug(slug);if(c&&c.pub&&!S.viewed.has(c.id)){S.viewed.add(c.id);track(c.id,'v')}}};
ACT.shareC=async a=>{const c=compById(a.dataset.cid)||{};const ct=c.contacts||{};const txt=`${c.pubName||c.name} — ${catName(c.pubCat)} em ${site().city}. Encontre no ${site().name}.${ct.whatsapp?' WhatsApp: '+ct.whatsapp:''}${ct.phone?' Tel: '+ct.phone:''}`;try{await navigator.clipboard.writeText(txt);toast('Texto de divulgação copiado. Cole onde quiser compartilhar.','ok')}catch(e){modal(`<h3>Compartilhar</h3><p class="sm">Copie o texto abaixo:</p><textarea class="inp" style="min-height:100px" readonly>${esc(txt)}</textarea>`)}};
ACT.lightbox=a=>modal(`<div class="lightbox"><img src="${esc(a.dataset.src)}" alt="${esc(a.dataset.cap)}">${a.dataset.cap?`<p class="sm" style="text-align:center;margin-top:10px">${esc(a.dataset.cap)}</p>`:''}</div>`,{wide:true});
FORM.review=async(f,o)=>{const cid=f.dataset.cid;const rating=+o.rating;if(!(rating>=1&&rating<=5))return toast('Escolha uma nota de 1 a 5.','err');if(await W(mutate('reviews/'+S.uid,()=>S.reviews[S.uid],v=>S.reviews[S.uid]=v,b=>{b.items=b.items||{};b.items[cid]={rating,text:(o.text||'').slice(0,600),at:now()}}),'Avaliação enviada. Obrigado!'))render(false)};
ACT.delReview=async a=>{if(!await confirmBox('Remover sua avaliação desta empresa?',{ok:'Remover',danger:true}))return;if(await W(mutate('reviews/'+S.uid,()=>S.reviews[S.uid],v=>S.reviews[S.uid]=v,b=>{if(b.items)delete b.items[a.dataset.cid]}),'Avaliação removida.'))render(false)};

/* ---------- categorias ---------- */
V.categorias={title:'Categorias',render(){const mc=mainCats();return ph('Categorias','Todas as categorias e subcategorias do guia comercial.')+`<div class="wrap sec">${mc.length?`<div class="grid g3">${mc.map(c=>{const col=CATCOLOR[c.icon]||'#287DA3';const subs=subCats(c.id);return`<div class="card"><a href="#categoria-${esc(c.id)}" class="row" style="color:inherit;gap:12px;text-decoration:none"><span class="ci" style="width:46px;height:46px;border-radius:12px;display:grid;place-items:center;background:${col}1a;color:${col}">${ic(c.icon,'l')}</span><h3 style="margin:0">${esc(c.name)}</h3></a><div class="row" style="margin-top:12px">${subs.slice(0,14).map(s=>`<a class="chip chip-gy" href="#empresas" ${fAttr({cat:c.id,sub:s.id})}>${esc(s.name)}</a>`).join('')}${subs.length>14?`<a class="chip" href="#categoria-${esc(c.id)}">+${subs.length-14}</a>`:''}</div></div>`}).join('')}</div>`:empty('Nenhuma categoria cadastrada.')}</div>`}};
V['categoria*']={title:p=>catName(p)||'Categoria',render(id){const c=catById(id);if(!c)return V['404'].render();const main=c.parent?catById(c.parent):c;const subs=subCats(main.id);const list=searchCompanies({...F0,cat:c.parent?'':c.id,sub:c.parent?c.id:''});const pr=activePromos().filter(p=>p.company&&(p.company.allCats.includes(c.id)||p.company.allCats.some(x=>catById(x)?.parent===c.id)));const col=CATCOLOR[main.icon]||'#287DA3';return`<div class="ph" style="background:linear-gradient(180deg,${col}14,#fff)"><div class="wrap"><div class="crumb"><a href="#categorias">Categorias</a>${c.parent?` › <a href="#categoria-${esc(main.id)}">${esc(main.name)}</a>`:''}</div><h1 class="row" style="gap:14px"><span style="color:${col}">${ic(main.icon,'l')}</span>${esc(c.name)}</h1><div class="row">${subs.map(s=>`<a class="chip ${s.id===c.id?'chip-or':'chip-gy'}" href="#categoria-${esc(s.id)}">${esc(s.name)}</a>`).join('')}</div></div></div><div class="wrap sec">${pr.length?`<h3>${ic('tag')} Ofertas nesta categoria</h3><div class="grid g4" style="margin-bottom:30px">${pr.slice(0,4).map(pCard).join('')}</div>`:''}<div class="row between"><h3>${nf(list.length)} empresa${list.length===1?'':'s'}</h3><a href="#empresas" ${fAttr({cat:c.parent?'':c.id,sub:c.parent?c.id:''})}>Filtrar no diretório</a></div>${list.length?`<div class="grid g4">${list.map(cCard).join('')}</div>`:empty('Nenhuma empresa nesta categoria ainda.','',`<a class="btn btn-p" href="#cadastro">Cadastre a sua</a>`)}</div>`}};

/* ---------- serviços e profissionais ---------- */
V.servicos={title:'Serviços',live:false,render(){return ph('Serviços','Serviços oferecidos pelas empresas e profissionais da cidade.')+`<div class="wrap sec"><div class="fld" style="max-width:480px"><label for="svcQ">Buscar serviço</label><input id="svcQ" type="search" placeholder="Ex.: instalação elétrica, limpeza, manicure"></div><div id="svcList"></div></div>`},after(){const draw=()=>{const q=slugify($('#svcQ').value);const items=pubCompanies().flatMap(c=>(c.products||[]).filter(p=>p.kind==='servico').map(p=>({p,c}))).filter(({p,c})=>!q||q==='item'||slugify(p.name+' '+(p.desc||'')+' '+c.pubName).includes(q));$('#svcList').innerHTML=items.length?`<div class="grid g3">${items.map(({p,c})=>`<a class="card" href="#empresa-${esc(c.slug)}" style="color:inherit;text-decoration:none;display:block"><span class="chip">${esc(catName(c.pubCat))}</span><h4 style="margin:10px 0 4px">${esc(p.name)}</h4><p class="sm muted" style="margin:0">${esc(p.desc||'')}</p><div class="row between" style="margin-top:10px"><span class="sm"><b>${esc(c.pubName)}</b></span>${num(p.price)?`<b style="color:#b25f17">${money(num(p.price))}</b>`:'<span class="xs muted">Sob consulta</span>'}</div></a>`).join('')}</div>`:empty('Nenhum serviço encontrado.','Empresas cadastram seus serviços no painel, em Produtos e serviços.')};$('#svcQ').oninput=draw;draw()},refresh(){$('#svcQ')?.dispatchEvent(new Event('input'))}};
V.profissionais={title:'Profissionais',render(){const list=pubCompanies().filter(c=>c.estab==='domiciliar'||c.personType==='pf');return ph('Profissionais autônomos','Eletricistas, diaristas, manicures, técnicos e outros profissionais que atendem na cidade.')+`<div class="wrap sec">${list.length?`<div class="grid g4">${list.map(cCard).join('')}</div>`:empty('Nenhum profissional publicado ainda.','',`<a class="btn btn-p" href="#cadastro">Cadastre-se como profissional</a>`)}</div>`}};

/* ---------- ofertas ---------- */
V.ofertas={title:'Ofertas',render(){const all=activePromos();const fc=S.oc||'';const fz=S.oz||'';const list=all.filter(p=>(!fc||p.company.allCats.includes(fc)||p.company.allCats.some(x=>catById(x)?.parent===fc))&&(!fz||p.company.loc?.zone===fz));const used=mainCats().filter(c=>all.some(p=>p.company.allCats.includes(c.id)||p.company.allCats.some(x=>catById(x)?.parent===c.id)));return ph('Ofertas da cidade','Promoções publicadas pelas empresas locais. Promoções vencidas saem do ar automaticamente.')+`<div class="wrap sec"><div class="row" style="margin-bottom:10px"><button class="chip ${!fc?'chip-or':'chip-gy'}" data-act="oc" data-v="">Todas</button>${used.map(c=>`<button class="chip ${fc===c.id?'chip-or':'chip-gy'}" data-act="oc" data-v="${esc(c.id)}">${esc(c.name)}</button>`).join('')}</div><div class="row" style="margin-bottom:22px"><span class="sm muted">Zona:</span><button class="chip ${!fz?'':'chip-gy'}" data-act="oz" data-v="">Todas</button>${zones().map(z=>`<button class="chip ${fz===z.id?'':'chip-gy'}" data-act="oz" data-v="${esc(z.id)}">${esc(z.name)}</button>`).join('')}</div>${list.length?`<div class="grid g4">${list.map(pCard).join('')}</div>`:empty('Nenhuma oferta ativa com esses filtros.')}</div>${adSlot('ofertas')}`}};
ACT.oc=a=>{S.oc=a.dataset.v;render(false)};ACT.oz=a=>{S.oz=a.dataset.v;render(false)};

/* ---------- eventos ---------- */
V.eventos={title:'Eventos',render(){const t=S.et||'';const evs=upcomingEvents().filter(e=>!t||e.type===t);const groups={};evs.forEach(e=>{const d=new Date((e.date||'')+'T12:00:00');const k=isNaN(d)?'Sem data':d.toLocaleDateString('pt-BR',{month:'long',year:'numeric'});(groups[k]=groups[k]||[]).push(e)});return ph('Eventos e agenda',`Shows, feiras, festas tradicionais e tudo o que acontece em ${esc(site().city)}.`)+`<div class="wrap sec"><div class="row" style="margin-bottom:22px"><button class="chip ${!t?'chip-or':'chip-gy'}" data-act="et" data-v="">Todos</button>${EVENT_TYPES.map(x=>`<button class="chip ${t===x?'chip-or':'chip-gy'}" data-act="et" data-v="${esc(x)}">${esc(x)}</button>`).join('')}</div>${Object.keys(groups).length?Object.entries(groups).map(([k,a])=>`<h3 style="text-transform:capitalize;margin-top:10px">${esc(k)}</h3><div class="grid g2" style="margin-bottom:22px">${a.map(eCard).join('')}</div>`).join(''):empty('Nenhum evento agendado.')}</div>`}};
ACT.et=a=>{S.et=a.dataset.v;render(false)};
V['evento*']={title:p=>allEvents().find(e=>e.id===p)?.title||'Evento',render(id){const e=allEvents().find(x=>x.id===id);if(!e)return V['404'].render();const u=safeImg(e.image?.url);const maps=e.address||e.place?`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent([e.address||e.place,site().city].join(', '))}`:'';return`<div class="article"><div class="crumb"><a href="#eventos">Eventos</a></div><span class="chip chip-mr">${esc(e.type||'Evento')}</span> ${demoTag(e)}<h1 style="font-size:clamp(26px,4vw,40px);margin-top:10px">${esc(e.title)}</h1>${u?`<img class="hero-img" src="${u}" alt="">`:''}<div class="card" style="margin:16px 0"><div class="grid g2" style="gap:10px"><div class="row">${ic('cal')}<span><b>${fmtD(e.date)}${e.endDate&&e.endDate!==e.date?' a '+fmtD(e.endDate):''}</b>${e.time?'<br>'+esc(e.time):''}</span></div><div class="row">${ic('pin')}<span><b>${esc(e.place||'')}</b>${e.address?'<br>'+esc(e.address):''}</span></div>${e.organizer||e.company?`<div class="row">${ic('users')}<span>Organização: <b>${esc(e.organizer||e.company?.pubName)}</b></span></div>`:''}</div><div class="row" style="margin-top:14px">${maps?`<a class="btn" href="${maps}" target="_blank" rel="noopener">${ic('map','s')} Ver no mapa</a>`:''}${e.link?`<a class="btn btn-b" href="${esc(safeUrl(e.link))}" target="_blank" rel="noopener">${ic('ext','s')} Link do evento</a>`:''}${e.company?`<a class="btn" href="#empresa-${esc(e.company.slug)}">Página do organizador</a>`:''}</div></div><p style="white-space:pre-line">${esc(e.description||'')}</p></div>`}};

/* ---------- turismo ---------- */
V.turismo={title:'Turismo',render(){const k=S.tk||'';const items=S.tourism.filter(t=>!k||t.kind===k);const hotels=companiesIn('turismo',8);const kinds=TOUR_KINDS.filter(x=>S.tourism.some(t=>t.kind===x));const hist=S.tourism.find(t=>t.kind==='História da cidade');return`<div class="ph" style="background:linear-gradient(135deg,#eef2e8,#fff 60%)"><div class="wrap"><div class="eyebrow" style="color:var(--vd)">Turismo e valorização regional</div><h1>Conheça ${esc(site().city)}</h1><p class="muted" style="max-width:680px">História, pontos turísticos, gastronomia típica, turismo rural, roteiros e o artesanato que fazem a identidade da região.</p><div class="row"><a class="btn btn-v" href="#mapa">${ic('map','s')} Mapa turístico</a>${hist?`<a class="btn" href="#turismo-${esc(hist.id)}">História da cidade</a>`:''}</div></div></div><div class="wrap sec"><div class="row" style="margin-bottom:22px"><button class="chip ${!k?'chip-vd':'chip-gy'}" data-act="tk" data-v="">Tudo</button>${kinds.map(x=>`<button class="chip ${k===x?'chip-vd':'chip-gy'}" data-act="tk" data-v="${esc(x)}">${esc(x)}</button>`).join('')}</div>${items.length?`<div class="grid g3">${items.map(tCard).join('')}</div>`:empty('Conteúdo turístico em preparação.','O administrador publica pontos, roteiros e história em Administração → Conteúdos.')}</div>${hotels.length?sec('Onde ficar e o que viver','Hotéis, pousadas, agências e experiências locais.',['#categoria-turismo','Ver todos'],`<div class="grid g4">${hotels.map(cCard).join('')}</div>`,'alt'):''}`}};
ACT.tk=a=>{S.tk=a.dataset.v;render(false)};
V['turismo*']={title:p=>S.tourism.find(t=>t.id===p)?.title||'Turismo',render(id){const t=S.tourism.find(x=>x.id===id);if(!t)return V['404'].render();const u=safeImg(t.image?.url);const rel=(t.companies||[]).map(compById).filter(c=>c?.pub);const steps=String(t.steps||'').split('\n').map(s=>s.trim()).filter(Boolean);const maps=t.address?`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(t.address+', '+site().city)}`:'';return`<div class="article"><div class="crumb"><a href="#turismo">Turismo</a></div><span class="chip chip-vd">${esc(t.kind)}</span> ${demoTag(t)}<h1 style="font-size:clamp(26px,4vw,40px);margin-top:10px">${esc(t.title)}</h1>${t.summary?`<p class="muted" style="font-size:19px">${esc(t.summary)}</p>`:''}${u?`<img class="hero-img" src="${u}" alt="">`:''}<p style="white-space:pre-line">${esc(t.body||'')}</p>${steps.length?`<div class="card"><h3>Roteiro sugerido</h3><ol style="margin:0;padding-left:20px">${steps.map(s=>`<li style="margin:6px 0">${esc(s)}</li>`).join('')}</ol></div>`:''}${maps?`<p><a class="btn" href="${maps}" target="_blank" rel="noopener">${ic('map','s')} Ver no mapa</a></p>`:''}${rel.length?`<h3 style="margin-top:26px">Estabelecimentos relacionados</h3><div class="grid g2">${rel.map(cCard).join('')}</div>`:''}</div>`}};

/* ---------- empregos, notícias, telefones ---------- */
V.empregos={title:'Empregos',render(){const j=allJobs();return ph('Vagas e oportunidades','Vagas publicadas por empresas locais e oportunidades de capacitação e empreendedorismo.')+`<div class="wrap sec"><div class="row between"><h3>${nf(j.length)} vaga${j.length===1?'':'s'} aberta${j.length===1?'':'s'}</h3>${S.uid?'<a class="btn btn-sm" href="#painel-vagas">Publicar vaga da minha empresa</a>':''}</div>${j.length?`<div class="list">${j.map(jobItem).join('')}</div>`:empty('Nenhuma vaga aberta no momento.')}${S.opps.length?`<h3 style="margin-top:38px">Oportunidades</h3><div class="grid g3">${S.opps.map(o=>`<div class="card"><span class="chip chip-vd">${esc(o.kind||'')}</span><h4 style="margin:10px 0 6px">${esc(o.title)}</h4><p class="sm muted">${esc(o.summary||'')}</p>${o.date?`<p class="xs">${ic('cal','s')} ${fmtD(o.date)}</p>`:''}${o.link?`<a href="${esc(safeUrl(o.link))}" target="_blank" rel="noopener" class="sm">Saiba mais ${ic('ext','s')}</a>`:''} ${demoTag(o)}</div>`).join('')}</div>`:''}</div>`}};
V.noticias={title:'Notícias',render(){const c=S.nc||'';const list=pubNews().filter(n=>!c||n.category===c);return ph('Notícias locais','Cidade, economia, comércio, cultura, turismo e serviços públicos.')+`<div class="wrap sec"><div class="row" style="margin-bottom:22px"><button class="chip ${!c?'chip-or':'chip-gy'}" data-act="nc" data-v="">Todas</button>${NEWS_CATS.map(x=>`<button class="chip ${c===x?'chip-or':'chip-gy'}" data-act="nc" data-v="${esc(x)}">${esc(x)}</button>`).join('')}</div>${list.length?`<div class="grid g3">${list.map(nCard).join('')}</div>`:empty('Nenhuma notícia nesta categoria.')}</div>`}};
ACT.nc=a=>{S.nc=a.dataset.v;render(false)};
V['noticia*']={title:p=>S.news.find(n=>n.id===p)?.title||'Notícia',render(id){const n=S.news.find(x=>x.id===id);if(!n||n.status==='rascunho')return V['404'].render();const u=safeImg(n.image?.url);return`<article class="article"><div class="crumb"><a href="#noticias">Notícias</a> › ${esc(n.category||'')}</div>${demoTag(n)}<h1 style="font-size:clamp(26px,4vw,42px);margin-top:8px">${esc(n.title)}</h1>${n.summary?`<p class="muted" style="font-size:19px">${esc(n.summary)}</p>`:''}<p class="sm muted">${fmtD(n.publishedAt)}${n.author?' · '+esc(n.author):''}</p>${u?`<img class="hero-img" src="${u}" alt="">`:''}<div style="white-space:pre-line">${esc(n.body||'')}</div></article>`}};
V['telefones-uteis']={title:'Telefones úteis',live:false,render(){return ph('Telefones úteis','Contatos essenciais validados pelo administrador do portal. Em emergência, ligue imediatamente.')+`<div class="wrap sec"><div class="row" style="margin-bottom:18px"><input id="telQ" class="inp" type="search" placeholder="Buscar contato" aria-label="Buscar contato" style="max-width:340px"><select id="telC" class="inp" style="width:auto" aria-label="Categoria"><option value="">Todas as categorias</option>${PHONE_CATS.map(c=>`<option>${esc(c)}</option>`).join('')}</select></div><div id="telList"></div><p class="xs muted" style="margin-top:16px">Se o botão de ligação não abrir no seu dispositivo, disque o número exibido.</p></div>`},after(){const draw=()=>{const q=slugify($('#telQ').value),c=$('#telC').value;const l=S.phones.filter(p=>(!c||p.category===c)&&(!$('#telQ').value||slugify(p.name+' '+p.category).includes(q))).sort((a,b)=>(a.category==='Emergência'?0:1)-(b.category==='Emergência'?0:1)||(a.order||99)-(b.order||99)||String(a.name).localeCompare(b.name));const groups={};l.forEach(p=>(groups[p.category||'Outros']=groups[p.category||'Outros']||[]).push(p));$('#telList').innerHTML=l.length?Object.entries(groups).map(([k,a])=>`<h3 style="margin-top:14px">${esc(k)}</h3><div class="grid g2">${a.map(phoneItem).join('')}</div>`).join(''):empty('Nenhum contato encontrado.')};$('#telQ').oninput=draw;$('#telC').onchange=draw;draw()},refresh(){$('#telQ')?.dispatchEvent(new Event('input'))}};

/* ---------- bairros e mapa ---------- */
V.bairros={title:'Bairros e zonas',render(){const pc=pubCompanies();return ph('Bairros e zonas',`Navegue pela divisão territorial de ${esc(site().city)}: Cidade → Zona → Bairro → Empresas.`)+`<div class="wrap sec">${zones().length?zones().map(z=>{const n=pc.filter(c=>c.loc?.zone===z.id).length;return`<div class="card"><div class="row between"><h3 style="margin:0">${ic('pin')} Zona ${esc(z.name)}</h3><a href="#empresas" ${fAttr({zone:z.id})}>${nf(n)} empresa${n===1?'':'s'} ${ic('right','s')}</a></div><div class="zones" style="margin-top:14px">${(z.bairros||[]).map(b=>{const m=pc.filter(c=>c.loc?.bairro===b.id).length;return`<button class="zone" ${fAttr({zone:z.id,bairro:b.id})}><h4>${esc(b.name)}</h4><span class="sm muted">${nf(m)} empresa${m===1?'':'s'}</span></button>`}).join('')||'<p class="muted sm">Nenhum bairro cadastrado nesta zona.</p>'}</div></div>`}).join(''):empty('Zonas ainda não configuradas.')}</div>`}};
function hashN(s){let h=0;for(const ch of String(s))h=(h*31+ch.charCodeAt(0))>>>0;return h}
const ZPOS={centro:[500,270],norte:[500,95],sul:[500,445],leste:[820,270],oeste:[180,270],rural:[860,450]};
V.mapa={title:'Mapa',render(){const layer=S.ml||'empresas';const zs=zones();const pos={};zs.forEach((z,i)=>{const key=slugify(z.name);pos[z.id]=ZPOS[key]||[160+(i%4)*230,95+Math.floor(i/4)*175]});const pc=pubCompanies().filter(c=>!S.mc||c.allCats.includes(S.mc)||c.allCats.some(x=>catById(x)?.parent===S.mc));
 const pins=layer==='empresas'?pc.filter(c=>pos[c.loc?.zone]).map(c=>{const[x,y]=pos[c.loc.zone];const h=hashN(c.id);return`<g class="pin" data-act="mapPin" data-cid="${esc(c.id)}" tabindex="0" role="button" aria-label="${esc(c.pubName)}" transform="translate(${x+((h%120)-60)} ${y+(((h>>8)%80)-40)})"><circle r="7" fill="${catColor(c.pubCat)}" stroke="#fff" stroke-width="2.5"/></g>`}).join(''):S.tourism.filter(t=>t.zone&&pos[t.zone]).map(t=>{const[x,y]=pos[t.zone];const h=hashN(t.id);return`<a href="#turismo-${esc(t.id)}"><g class="pin" transform="translate(${x+((h%120)-60)} ${y+(((h>>8)%80)-40)})"><circle r="8" fill="var(--vd)" stroke="#fff" stroke-width="2.5"/><title>${esc(t.title)}</title></g></a>`}).join('');
 return ph('Mapa da cidade','Mapa interativo por zonas. Toque em um ponto para ver a empresa.')+`<div class="wrap sec"><div class="row" style="margin-bottom:14px"><button class="chip ${layer==='empresas'?'chip-or':'chip-gy'}" data-act="ml" data-v="empresas">${ic('store','s')} Empresas</button><button class="chip ${layer==='turismo'?'chip-vd':'chip-gy'}" data-act="ml" data-v="turismo">${ic('travel','s')} Mapa turístico</button>${layer==='empresas'?`<select class="inp" style="width:auto;min-height:36px" data-act="noop" id="mapCat" aria-label="Categoria"><option value="">Todas as categorias</option>${mainCats().map(c=>`<option value="${esc(c.id)}" ${S.mc===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select>`:''}</div>
 <div class="mapwrap"><svg viewBox="0 0 1000 540" role="img" aria-label="Mapa esquemático por zonas"><rect width="1000" height="540" fill="#f3efe7"/><g fill="none" stroke="#e4ddcf" stroke-width="18" stroke-linecap="round"><path d="M0 270 H1000"/><path d="M500 0 V540"/><path d="M80 520 C 300 380, 700 420, 980 120"/></g><g fill="none" stroke="#fff" stroke-width="4"><path d="M0 270 H1000"/><path d="M500 0 V540"/></g><path d="M0 500 C 220 470, 420 520, 600 480 S 900 500, 1000 470" stroke="#9fd3e6" stroke-width="10" fill="none" opacity=".7"/>${zs.map(z=>{const[x,y]=pos[z.id];return`<g><ellipse cx="${x}" cy="${y}" rx="120" ry="72" fill="${slugify(z.name)==='rural'?'#718A52':'#55B7D9'}" opacity=".12"/><text x="${x}" y="${y-58}" text-anchor="middle" font-family="Montserrat" font-weight="700" font-size="15" fill="#29343A">${esc(z.name)}</text></g>`}).join('')}${pins}</svg></div><div id="mapInfo" style="margin-top:14px"></div><p class="xs muted" style="margin-top:10px">Mapa esquemático: os pontos são posicionados pela zona cadastrada. A rota exata de cada empresa abre no Google Maps em “Como chegar”.</p></div>`},after(){const s=$('#mapCat');if(s)s.onchange=()=>{S.mc=s.value;render(false)}}};
ACT.ml=a=>{S.ml=a.dataset.v;render(false)};ACT.noop=()=>{};
ACT.mapPin=a=>{const c=compById(a.dataset.cid);if(c)$('#mapInfo').innerHTML=`<div style="max-width:380px">${cCard(c)}</div>`};

/* ---------- planos e páginas institucionais ---------- */
function planBenefits(p){return[`Página da empresa com categoria e localização`,`Telefone e WhatsApp`,`Até ${nf(p.photos)} fotos na galeria`,p.promos?`Até ${nf(p.promos)} promoç${p.promos>1?'ões':'ão'} simultânea${p.promos>1?'s':''}`:'Sem promoções',p.reports?'Relatórios de visualização':'',p.advanced?'Estatísticas avançadas':'',p.highlight?'Destaque identificado nas categorias':'',p.events?'Divulgação de eventos próprios':'',p.banners?'Banners comerciais':'',...(String(p.extra||'').split('\n').filter(Boolean))].filter(Boolean)}
V.planos={title:'Planos',render(){const ps=plans();return ph('Planos para empresas','Comece gratuitamente. Os valores e benefícios são definidos pela administração do portal.')+`<div class="wrap sec">${ps.length?`<div class="grid g3">${ps.map((p,i)=>`<div class="card" style="${i===1?'border:2px solid var(--lj);':''}display:flex;flex-direction:column">${i===1?'<span class="chip chip-or" style="align-self:flex-start;margin-bottom:8px">Mais escolhido</span>':''}<h3 style="font-size:22px">${esc(p.name)}</h3><p style="font-family:Montserrat;font-size:26px;font-weight:800;margin:0 0 12px">${esc(p.priceText||'Sob consulta')}</p><ul style="padding-left:18px;margin:0 0 18px;flex:1">${planBenefits(p).map(b=>`<li class="sm" style="margin:5px 0">${esc(b)}</li>`).join('')}</ul><a class="btn ${i===1?'btn-p':'btn-b'}" href="#${S.uid?'painel-plano':'cadastro'}">${p.id==='gratuito'?'Começar grátis':'Solicitar este plano'}</a></div>`).join('')}</div><p class="xs muted" style="margin-top:16px">Pagamento online por assinatura será integrado em uma próxima etapa. Hoje o administrador ativa o plano após combinar a forma de pagamento.</p>`:empty('Planos ainda não configurados.')}</div>`}};
V.termos={title:'Termos de uso',render(){return`<div class="article"><h1>Termos de uso</h1><p class="note or">${ic('alert')} Modelo inicial para o protótipo — revise com assessoria jurídica antes da publicação oficial.</p><p>O ${esc(site().name)} é um guia digital que conecta moradores, visitantes e empresas de ${esc(site().city)}. Ao cadastrar uma empresa, o responsável declara que as informações são verdadeiras e que tem autorização para divulgá-las.</p><p>Todo cadastro, promoção, evento e vaga passa por moderação e pode ser recusado, suspenso ou removido quando contrariar a lei, estes termos ou o interesse público.</p><p>É proibido publicar conteúdo enganoso, ofensivo, ilegal ou que viole direitos de terceiros. Promoções devem informar condições reais e período de validade.</p><p>Avaliações devem refletir experiências reais e são moderadas.</p></div>`}};
V.privacidade={title:'Privacidade e LGPD',render(){return`<div class="article"><h1>Privacidade e proteção de dados</h1><p class="note or">${ic('alert')} Modelo inicial para o protótipo — revise com o encarregado de dados (DPO) antes da publicação oficial.</p><p><b>Dados coletados.</b> Do responsável pela empresa: nome, e-mail, telefone e WhatsApp. Da empresa: informações comerciais públicas. CPF/CNPJ é usado apenas para verificação e não é exibido publicamente.</p><p><b>Acesso restrito.</b> Os dados pessoais do responsável e os documentos ficam em área privada, visível somente ao próprio titular e à administração.</p><p><b>Métricas.</b> Visualizações e cliques são contados de forma agregada por empresa, sem exibir quem visitou.</p><p><b>Direitos do titular.</b> Você pode consultar, corrigir e excluir seus dados a qualquer momento em Painel → Configurações da conta.</p><p><b>Localização.</b> A busca por proximidade usa apenas o bairro que você informar.</p></div>`}};
V['404']={title:'Página não encontrada',render(){return ph('Página não encontrada')+`<div class="wrap sec">${empty('O endereço acessado não existe ou foi removido.','',`<a class="btn" href="#inicio">Voltar ao início</a>`)}</div>`}};

/* ---------- autenticação ---------- */
V.entrar={title:'Entrar',render(){if(S.uid)return ph('Você já está conectado')+`<div class="wrap sec"><div class="card" style="max-width:640px"><p>Conectado como <b>${esc(S.me?.name||'sua conta')}</b>.</p><div class="row"><a class="btn btn-p" href="#painel">Ir para o painel</a>${S.admin?'<a class="btn" href="#admin">Administração</a>':''}</div></div></div>`;return ph('Entrar no portal')+`<div class="wrap sec"><div class="card" style="max-width:680px">${ic('lock','l')}<h3 style="margin-top:10px">Acesso com a sua conta</h3><p>Neste protótipo, a autenticação é real e usa a conta com que você abre o portal: não há senha própria a criar nem a recuperar aqui, e a sessão é gerenciada com segurança pela plataforma.</p><p class="muted sm">Na versão de produção (Next.js + Supabase Auth), esta tela terá e-mail e senha, verificação de e-mail, recuperação de senha e bloqueio de tentativas abusivas, conforme o escopo do projeto.</p><p class="sm">Você está vendo o portal sem uma conta conectada. Abra-o já conectado à sua conta para cadastrar empresas.</p></div></div>`}};
V['recuperar-senha']={title:'Recuperar senha',render(){return ph('Recuperar senha')+`<div class="wrap sec"><div class="card" style="max-width:640px"><p>O acesso deste protótipo usa a sua conta conectada; a senha é gerenciada pela plataforma onde você entrou. Na versão de produção, esta página enviará um link de redefinição para o e-mail cadastrado.</p><a class="btn" href="#entrar">Voltar</a></div></div>`}};
V['verificar-email']={title:'Verificar e-mail',render(){return ph('Verificação de e-mail')+`<div class="wrap sec"><div class="card" style="max-width:640px"><p>${S.uid?'Sua conta já está verificada pela plataforma de acesso.':'Entre com sua conta para continuar.'} Na versão de produção, um link de confirmação será enviado ao e-mail informado no cadastro.</p><a class="btn btn-p" href="#painel">Ir para o painel</a></div></div>`}};
V.cadastro={title:'Criar conta',auth:'user',live:false,render(){const me=S.me||{};const done=!!me.acceptedAt;return ph(done?'Seus dados de responsável':'Crie sua conta de empresário','Passo 1 de 2 — depois você cadastra sua empresa em etapas simples.')+`<div class="wrap sec"><form class="card" style="max-width:720px" data-form="signup" novalidate><div class="fgrid"><div class="fld full"><label for="suName">Nome completo do responsável *</label><input id="suName" type="text" name="name" value="${esc(me.name||'')}" required autocomplete="name"></div><div class="fld"><label for="suEmail">E-mail *</label><input id="suEmail" type="email" name="email" value="${esc(me.email||'')}" required autocomplete="email"></div><div class="fld"><label for="suPhone">Telefone *</label><input id="suPhone" type="tel" name="phone" value="${esc(me.phone||'')}" required placeholder="(00) 0000-0000" data-mask="phone"></div><div class="fld"><label for="suWa">WhatsApp</label><input id="suWa" type="tel" name="whatsapp" value="${esc(me.whatsapp||'')}" placeholder="(00) 90000-0000" data-mask="phone"></div></div><label class="chk"><input type="checkbox" name="terms" ${done?'checked':''} required> Li e aceito os <a href="#termos" target="_blank">termos de uso</a> e a <a href="#privacidade" target="_blank">política de privacidade</a>.</label><div class="note" style="margin:14px 0">${ic('lock')} <span>Seus dados pessoais ficam em área privada: só você e a administração do portal podem vê-los. A senha e a sessão são gerenciadas pela sua conta conectada.</span></div><button class="btn btn-p">${done?'Salvar dados':'Criar conta e continuar'}</button></form></div>`}};
FORM.signup=async(f,o)=>{clearErr(f);let bad=false;if(o.name.length<5||!o.name.includes(' ')){fieldErr(f,'name','Informe nome e sobrenome.');bad=true}if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(o.email)){fieldErr(f,'email','E-mail inválido.');bad=true}if(digits(o.phone).length<10){fieldErr(f,'phone','Telefone com DDD.');bad=true}if(o.whatsapp&&digits(o.whatsapp).length<10){fieldErr(f,'whatsapp','WhatsApp com DDD.');bad=true}if(!o.terms){toast('É preciso aceitar os termos e a política de privacidade.','err');bad=true}if(bad)return;const first=!S.me?.acceptedAt;if(await W(mutatePriv(b=>{Object.assign(b,{name:o.name,email:o.email,phone:o.phone,whatsapp:o.whatsapp,acceptedAt:b.acceptedAt||now(),termsVersion:'1.0',createdAt:b.createdAt||now()})}),first?'Conta criada!':'Dados salvos.')){if(first)go(myCompanies().length?'painel':'painel-nova');else render(false)}};

/* ---------- eventos globais ---------- */
function maskPhone(v){const d=digits(v).slice(0,11);if(d.length<=2)return d;if(d.length<=6)return`(${d.slice(0,2)}) ${d.slice(2)}`;if(d.length<=10)return`(${d.slice(0,2)}) ${d.slice(2,6)}-${d.slice(6)}`;return`(${d.slice(0,2)}) ${d.slice(2,7)}-${d.slice(7)}`}
document.addEventListener('input',e=>{const m=e.target.dataset?.mask;if(m==='phone')e.target.value=maskPhone(e.target.value);if(m==='cep'){const d=digits(e.target.value).slice(0,8);e.target.value=d.length>5?d.slice(0,5)+'-'+d.slice(5):d}if(m==='doc'){const d=digits(e.target.value).slice(0,14);e.target.value=d.length<=11?d.replace(/(\d{3})(\d{3})?(\d{3})?(\d{1,2})?/,(x,a,b,c,dd)=>[a,b,c].filter(Boolean).join('.')+(dd?'-'+dd:'')):d.replace(/(\d{2})(\d{3})(\d{3})(\d{4})(\d{0,2})/,'$1.$2.$3/$4-$5')}});
document.addEventListener('click',e=>{const tr=e.target.closest('[data-track]');if(tr&&tr.dataset.cid)track(tr.dataset.cid,tr.dataset.track);const a=e.target.closest('[data-act]');if(a){const f=ACT[a.dataset.act];if(f){if(a.tagName!=='SELECT')e.preventDefault();f(a,e)}return}const g=e.target.closest('[data-f]');if(g){e.preventDefault();S.f={...F0,...JSON.parse(g.dataset.f)};resLimit=24;go('empresas')}if(!e.target.closest('#umenu'))$('#umenu')?.classList.remove('open')});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#modalRoot').classList.contains('on'))ACT.mNo();if(e.key==='Enter'&&e.target.closest?.('.pin[data-act]'))ACT.mapPin(e.target.closest('.pin'))});
document.addEventListener('submit',e=>{const f=e.target.closest('form[data-form]');if(!f)return;e.preventDefault();const h=FORM[f.dataset.form];if(h){const btn=f.querySelector('button:not([type=button])');if(btn){btn.disabled=true;setTimeout(()=>btn.disabled=false,1200)}Promise.resolve(h(f,formObj(f))).catch(err=>{console.error(err);toast(err.message||'Erro inesperado.','err')})}});
ACT.mYes=()=>{const r=modalRes;modalRes=null;closeModal();r?.(true)};
ACT.mYesP=()=>{const v=($('#promptVal')?.value||'').trim();if($('#promptVal')?.required&&!v){$('#promptVal').focus();return toast('Preencha o campo.','err')}const r=modalRes;modalRes=null;r?.(true);closeModal()};
ACT.mNo=()=>{const r=modalRes;modalRes=null;closeModal();r?.(false)};
ACT.umenu=()=>$('#umenu')?.classList.toggle('open');
ACT.drawer=()=>{renderDrawer();$('#drawer').classList.add('on')};ACT.drawerClose=()=>$('#drawer').classList.remove('on');
